package vn.iotstar.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.PageRequest; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import vn.iotstar.dto.ProductDTO; import vn.iotstar.entity.Product; import vn.iotstar.repository.*;
@Controller @RequiredArgsConstructor public class ProductController{final ProductRepository products;final CategoryRepository cats;final UserRepository users;@GetMapping("/products")String list(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="0")int page,Model m){m.addAttribute("products",products.findByNameContainingIgnoreCaseOrDescriptionContainingIgnoreCase(q,q,PageRequest.of(Math.max(0,page),10)));return "products/list";}@GetMapping("/products/new")String form(Model m){m.addAttribute("form",new ProductDTO());m.addAttribute("categories",cats.findAll());return "products/form";}@PostMapping("/products/save")String save(@Valid @ModelAttribute("form")ProductDTO d,BindingResult b,Authentication a,Model m){if(b.hasErrors()){m.addAttribute("categories",cats.findAll());return "products/form";}var p=new Product();p.setName(d.getName());p.setPrice(d.getPrice());p.setDescription(d.getDescription());p.setCategory(cats.findById(d.getCategoryId()).orElseThrow());p.setUser(users.findByUsername(a.getName()).orElseThrow());products.save(p);return "redirect:/products";}@PostMapping("/products/delete/{id}")String del(@PathVariable Long id){products.deleteById(id);return "redirect:/products";}}
